/// Freehand's bend controller (picture 46): above the pivot (Freehand:Lower, a share of the
/// length) the spine turns round Freehand:Axis, little by little along the band up to the top
/// handle (Freehand:Upper), by Freehand:Angle degrees in all; past the top it keeps that
/// direction. Bend shape is how the turning spreads over the band (1 evenly, below 1 sooner
/// near the pivot, above 1 later near the top). Lengths are kept.
fn freehand_bend(pts: &mut Vec<Vec3>, p: &Params) {
    let ang = pex(p, "Freehand:Angle", 0.0);
    if ang.abs() < 0.01 || pts.len() < 2 {
        return;
    }
    let axis = vec3(pex(p, "Freehand:AxisX", 0.0), pex(p, "Freehand:AxisY", 0.0), pex(p, "Freehand:AxisZ", 1.0)).normalize_or_zero();
    if axis == Vec3::ZERO {
        return;
    }
    let lo = pex(p, "Freehand:Lower", 0.3).clamp(0.0, 0.95);
    let hi = pex(p, "Freehand:Upper", 1.0).clamp(lo + 0.05, 1.0);
    let shape = pex(p, "Freehand:Shape", 1.0).clamp(0.2, 4.0);
    let mut cum = vec![0.0f32; pts.len()];
    for k in 1..pts.len() {
        cum[k] = cum[k - 1] + pts[k].distance(pts[k - 1]);
    }
    let total = cum[pts.len() - 1].max(1e-5);
    let mut out = vec![pts[0]];
    for k in 1..pts.len() {
        let s = (cum[k - 1] + cum[k]) * 0.5 / total;
        let w = ((s - lo) / (hi - lo)).clamp(0.0, 1.0).powf(shape);
        let q = Quat::from_axis_angle(axis, ang.to_radians() * w);
        let prev = out[k - 1];
        out.push(prev + q * (pts[k] - pts[k - 1]));
    }
    *pts = out;
}

